/***************
Synoptic hl2
goes through and updates all objects with the new synoptic view
***************/


function updatesynoptic()
{
	exist = Dictionary.GetObject("ValveBiped", false);
	if (!exist)
		{
			logmessage ("No Valve Biped Found", siFatal);
			return;
		}
	getsynopticpath();
	if (synoptic == 0)
		{
			return;
		}
	logmessage ("Synoptic located at");
	logmessage (synoptic);
	
	//ok now select all animateable controls
	SelectObj("ValveBiped.Plotted", null, null);
	SelectMembers("ValveBiped.Plotted", null, null);
	
	//and update synoptic on all these objects

	for (i=0; i < selection.count ; i++)
		{
			obj = selection(i);
			synprop = (obj + ".Synoptic_Property");
			synname = (obj + ".Synoptic_Property.displayname");
			synpath = (obj + ".Synoptic_Property.path");
			//check if object has a synoptic property 
			//if it does just point it to the new one, if not add the prop
			chkexist = Dictionary.GetObject(synprop, false);
			if (!chkexist)
				{
					SelectObj(obj);
					AddProp("Synoptic Property", "", "", "", null);
				}
				SetValue(synname, "ValveBipedSynoptic", null);
				SetValue(synpath, synoptic, null);
		}
		DeselectAll();
}
	


function getsynopticpath()
{

	vproject = XSIUtils.Environment("VProject");
	synopticpath= ("\\game\\sdktools\\XSI\\5.0\\ValveSource\\Data\\Synoptic\\ValveBipedSynoptic_Rig.htm");
	//back up from the vproject and get the pose library path
	fso = new ActiveXObject("Scripting.FileSystemObject");
	f = fso.GetFolder(vproject); 
	game = f.ParentFolder;
	main = game.ParentFolder;
	synoptic = (main + synopticpath);
	//check if it exists
	fso = new ActiveXObject("Scripting.FileSystemObject");
	exists = fso.FileExists(synoptic);
	if (!exists)
		{
			logmessage ("Can't find Synoptic file. Get latest on the arttools", siFatal);
			synoptic = 0;
		}
	return (synoptic);
}

